sys_script_include.script:
var Overall = Class.create();
Overall.prototype = {
    initialize: function () {},

    createTasks: function () {
        var createdTasks = [];
        var processedProperties = []; // Track processed properties

        var kpiProperties = ['custombulk.property'];

        for (var i = 0; i < kpiProperties.length; i++) {
            var propertyName = kpiProperties[i];
            var kpiData = gs.getProperty(propertyName);

            if (!kpiData) {
                gs.error('Property "' + propertyName + '" is empty or not set.');
                continue;
            }

            processedProperties.push(propertyName); // Record property processed
            gs.info('Processing Property: ' + propertyName);

            try {
                var kpis = JSON.parse(kpiData);
                for (var j = 0; j < kpis.length; j++) {
                    var kpi = kpis[j];

                    if (!kpi.kpi || !kpi.table || !kpi.field || !kpi.description || !kpi.recommendation) {
                        gs.error('Missing required fields for KPI: ' + JSON.stringify(kpi));
                        continue;
                    }

                    var gscheck = new GlideRecord(kpi.table);
                    gscheck.addEncodedQuery(kpi.field);
                    gscheck.query();

                    if (!gscheck.next()) {
                        gs.error('No data for query: ' + kpi.field + ' on table: ' + kpi.table);
                        continue;
                    }

                    var existingTask = new GlideRecord('samp_sp_vb_task');
                    existingTask.addQuery('name', kpi.kpi);
                    existingTask.addQuery('description', kpi.description);
                    existingTask.addEncodedQuery('stateNOT IN2,-5,3,7');
                    existingTask.query();

                    if (existingTask.next()) {
                        gs.info('Task already exists for KPI: ' + kpi.kpi);
                        continue;
                    }

                    var taskGr = new GlideRecord('samp_sp_vb_task');
                    taskGr.initialize();
                    taskGr.setValue('name', kpi.kpi);
                    taskGr.setValue('short_description', kpi.description);
                    taskGr.setValue('description', kpi.description);
                    taskGr.setValue('instructions', kpi.recommendation);

                    var taskId = taskGr.insert();
                    if (taskId) {
                        gs.info('Created task for KPI: ' + kpi.kpi + ' (Task ID: ' + taskId + ')');
                        createdTasks.push(kpi.kpi);
                        gs.eventQueue('sam.implementation.value.builder.task', taskGr, taskGr.sys_id);
                    }
                }
            } catch (e) {
                gs.error('Error processing property "' + propertyName + '": ' + e.message);
            }
        }

        // Return both created tasks and processed properties
        return {
            createdTasks: createdTasks,
            processedProperties: processedProperties
        };
    },

    type: 'Overall'
};
